export type Ball = { x: number; y: number; vx: number; vy: number; r: number };

export const W = 400;
export const H = 300;
export const R = 10;
export const GRAVITY = 0.2;

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

export function makeBall(existing: Ball[] = []): Ball {
  let b: Ball = { x: 0, y: 0, vx: 0, vy: 0, r: R };
  for (let attempt = 0; attempt < 50; attempt++) {
    b = {
      x: rand(R, W - R),
      y: rand(R, H - R),
      vx: rand(-3, 3),
      vy: rand(-3, 3),
      r: R,
    };
    const overlaps = existing.some(
      (o) => Math.hypot(o.x - b.x, o.y - b.y) < o.r + b.r
    );
    if (!overlaps) break;
  }
  return b;
}

export function makeBalls(n: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(makeBall(balls));
  return balls;
}

function clamp(b: Ball): void {
  if (b.x < b.r) {
    b.x = b.r;
    b.vx = Math.abs(b.vx);
  } else if (b.x > W - b.r) {
    b.x = W - b.r;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y < b.r) {
    b.y = b.r;
    b.vy = Math.abs(b.vy);
  } else if (b.y > H - b.r) {
    b.y = H - b.r;
    b.vy = -Math.abs(b.vy);
  }
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;
    clamp(b);
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.hypot(dx, dy);
      const minDist = a.r + b.r;
      if (dist < minDist) {
        const nx = dist > 0 ? dx / dist : 1;
        const ny = dist > 0 ? dy / dist : 0;
        const rel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
        if (rel < 0) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
        const overlap = (minDist - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        clamp(a);
        clamp(b);
      }
    }
  }
}

const COLORS = ["#e11d48", "#2563eb", "#16a34a", "#f59e0b", "#9333ea", "#0891b2"];

export function draw(canvas: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, W, H);
  balls.forEach((b, i) => {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = COLORS[i % COLORS.length];
    ctx.fill();
  });
}

