use "./sim.ts" { makeBall, makeBalls, step, draw }

page Home "/" {
  state count = 0
  state frames = 0
  state paused = false
  ref box
  ref balls
  ref raf

  fn tick() {
    step(balls)
    draw(box, balls)
    frames++
    raf = requestAnimationFrame(tick)
  }

  fn toggle() {
    if paused {
      paused = false
      raf = requestAnimationFrame(tick)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  fn add() {
    balls.push(makeBall(balls))
    count = balls.length
    if paused {
      draw(box, balls)
    }
  }

  fn reset() {
    balls = makeBalls(5)
    count = balls.length
    frames = 0
    draw(box, balls)
  }

  mount {
    reset()
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" -> add()
      button `${paused ? "Reanudar" : "Pausar"}` primary -> toggle()
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

