export interface Ball {
  x: number
  y: number
  vx: number
  vy: number
  r: number
}

export const W = 400
export const H = 300
const R = 10
const G = 0.2

function rand(a: number, b: number): number {
  return a + Math.random() * (b - a)
}

export function newBall(existing: Ball[] = []): Ball {
  let b: Ball = { x: 0, y: 0, vx: 0, vy: 0, r: R }
  for (let tries = 0; tries < 50; tries++) {
    b = {
      x: rand(R, W - R),
      y: rand(R, H - R),
      vx: rand(-3, 3),
      vy: rand(-3, 3),
      r: R,
    }
    const overlaps = existing.some(o => Math.hypot(o.x - b.x, o.y - b.y) < o.r + b.r)
    if (!overlaps) break
  }
  return b
}

export function makeBalls(n: number): Ball[] {
  const balls: Ball[] = []
  for (let i = 0; i < n; i++) balls.push(newBall(balls))
  return balls
}

function clamp(b: Ball): void {
  if (b.x < b.r) {
    b.x = b.r
    b.vx = Math.abs(b.vx)
  } else if (b.x > W - b.r) {
    b.x = W - b.r
    b.vx = -Math.abs(b.vx)
  }
  if (b.y < b.r) {
    b.y = b.r
    b.vy = Math.abs(b.vy)
  } else if (b.y > H - b.r) {
    b.y = H - b.r
    b.vy = -Math.abs(b.vy)
  }
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += G
    b.x += b.vx
    b.y += b.vy
    clamp(b)
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i]
      const b = balls[j]
      const dx = b.x - a.x
      const dy = b.y - a.y
      const dist = Math.hypot(dx, dy)
      const min = a.r + b.r
      if (dist < min) {
        const nx = dist === 0 ? 1 : dx / dist
        const ny = dist === 0 ? 0 : dy / dist
        const approaching = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny < 0
        if (approaching) {
          const tvx = a.vx
          const tvy = a.vy
          a.vx = b.vx
          a.vy = b.vy
          b.vx = tvx
          b.vy = tvy
        }
        const push = (min - dist) / 2
        a.x -= nx * push
        a.y -= ny * push
        b.x += nx * push
        b.y += ny * push
        clamp(a)
        clamp(b)
      }
    }
  }
}

export function draw(ctx: CanvasRenderingContext2D, balls: Ball[]): void {
  ctx.clearRect(0, 0, W, H)
  ctx.fillStyle = "#f8fafc"
  ctx.fillRect(0, 0, W, H)
  ctx.strokeStyle = "#cbd5e1"
  ctx.strokeRect(0.5, 0.5, W - 1, H - 1)
  balls.forEach((b, i) => {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fillStyle = `hsl(${(i * 67) % 360}, 70%, 50%)`
    ctx.fill()
  })
}

