// "2026-03-12" -> "12/03/2026" (sin pasar por Date, para evitar corrimientos de zona horaria)
export function formatFecha(iso: string): string {
  const [a, m, d] = iso.split("-");
  return `${d}/${m}/${a}`;
}

// 1200 -> "US$ 1.200"
export function formatUSD(n: number): string {
  const entero = Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `US$ ${entero}`;
}

// "Ana Rojas" -> "AR"
export function iniciales(nombre: string): string {
  return nombre
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((p) => p.charAt(0).toUpperCase())
    .join("");
}

// Color estable que depende del nombre
export function colorPara(nombre: string): string {
  let h = 0;
  for (let i = 0; i < nombre.length; i++) {
    h = (h * 31 + nombre.charCodeAt(i)) >>> 0;
  }
  return `hsl(${h % 360}, 55%, 45%)`;
}

