/** "2026-03-12" -> "12/03/2026" (sin pasar por Date para evitar husos horarios) */
export function fecha(iso: string): string {
  const [a, m, d] = iso.split("-");
  return `${d}/${m}/${a}`;
}

/** 1200 -> "US$ 1.200" (punto de miles, sin decimales) */
export function dinero(monto: number): string {
  const entero = Math.round(monto).toString();
  const conPuntos = entero.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `US$ ${conPuntos}`;
}

/** "Ana Rojas" -> "AR" */
export function iniciales(nombre: string): string {
  return nombre
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((p) => p.charAt(0).toUpperCase())
    .join("");
}

/** Color estable a partir del nombre */
export function colorDe(nombre: string): string {
  let h = 0;
  for (let i = 0; i < nombre.length; i++) {
    h = (h * 31 + nombre.charCodeAt(i)) >>> 0;
  }
  return `hsl(${h % 360}, 55%, 45%)`;
}

/** Ordena por fecha de llegada, la más temprana primero (sin mutar) */
export function ordenarPorLlegada<T extends { llegada: string }>(lista: T[]): T[] {
  return [...lista].sort((a, b) => a.llegada.localeCompare(b.llegada));
}
